  "Questo è il ruolo operativo assegnato nella commessa; non sostituisce nomine e incarichi di sicurezza. Le fasi descrivono l’avanzamento operativo. Il rapportino dichiara il lavoro; la sua approvazione e il riconoscimento di un SAL sono passaggi distinti.": "ده دور الشغل اللي اتحدد في الشغلانة؛ مش بديل عن تعيينات ومهام الأمان. المراحل بتوصف تقدم الشغل. التقرير اليومي بيقول الشغل اللي اتعمل؛ الموافقة عليه والاعتراف بـ SAL (كشف تقدم الأعمال) خطوات منفصلة.",
  "Qui arrivano i cantieri assegnati, l’esito dei tuoi rapportini e i messaggi dell’ufficio.": "هنا بتوصلك المواقع المتسلّمة ليك، ونتيجة تقاريرك اليومية، ورسايل المكتب.",
