  "Conferma fascia di bordo e interspazio da progetto, anche se pari a zero.": "أكّد شريط الطرف والمسافة بين الألواح من المشروع، حتى لو صفر.",
  "Dimensioni incompatibili o griglia eccessiva: verifica le misure.": "المقاسات مش متوافقة أو الشبكة كبيرة قوي: راجع المقاسات.",
